// Bundles the core into one file for the browser.
//
// Unity WebGL cannot import ES modules from a .jslib, and a bundler in the
// trust path is a bad property for something that pins money - IMPLEMENTATION
// section 3.6 says so about hashing. So this is deliberately the smallest
// possible bundler: it topologically sorts the imports, strips the import and
// export lines, and concatenates. No transforms, no minification, no renaming.
//
// The test that matters is bundle.test.js: the bundle must produce the same
// state hashes as the modules, or it is not the same core.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve, relative } from 'node:path';

const SRC = new URL('../src/', import.meta.url).pathname;
// BLWP_BUNDLE_OUT builds into another directory, so a test can build this
// source and compare it with what is committed; unset, it writes dist/ as ever.
const OUT = process.env.BLWP_BUNDLE_OUT ? process.env.BLWP_BUNDLE_OUT.replace(/\/?$/, '/') : new URL('../dist/', import.meta.url).pathname;

const seen = new Set();
const order = [];

function walk(file) {
  if (seen.has(file)) return;
  seen.add(file);
  const text = readFileSync(file, 'utf8');
  // Multi-line imports too: sim.js pulls twenty names out of state.js across
  // eight lines, and a line-anchored pattern misses every one of them - which
  // left the import statement in the bundle and produced a syntax error.
  for (const m of text.matchAll(/import\s[\s\S]*?from\s+'([^']+)';/g)) {
    walk(resolve(dirname(file), m[1]));
  }
  order.push(file);
}
walk(SRC + 'sim.js');
walk(SRC + 'state.js');

// Flat concatenation means one scope, so two modules exporting the same name
// would silently shadow each other - and the survivor would depend on file
// order. Better to refuse than to ship a bundle that is quietly a different
// program from the modules.
const declared = new Map();
for (const file of order) {
  const text = readFileSync(file, 'utf8');
  for (const m of text.matchAll(/^export\s+(?:const|function|class|let|var)\s+([A-Za-z_$][\w$]*)/gm)) {
    const name = m[1];
    if (declared.has(name) && declared.get(name) !== file) {
      console.error('bundle: ' + name + ' is exported by both ' +
                    relative(SRC, declared.get(name)) + ' and ' + relative(SRC, file));
      process.exit(1);
    }
    declared.set(name, file);
  }
}

let out = '';
out += '// GENERATED by tools/bundle.js from @blwp/core. Do not edit.\n';
out += '// Verified against the module build by test/bundle.test.js.\n';
out += 'var BLWP = (function () {\n"use strict";\n';
for (const file of order) {
  const body = readFileSync(file, 'utf8')
    // AN IMPORT UNDER ANOTHER NAME KEEPS THAT NAME. `import { heat as
    // heatForLoad }` was stripped like any import, so the flat bundle had `heat`
    // and no `heatForLoad`, and the page threw "heatForLoad is not defined" on
    // every ROLL OUT (two-Chrome look, 2026-09-10) - the modules and every
    // suite that loads them were fine. The alias becomes a declaration where
    // the import stood; the module it names is earlier in `order`.
    .replace(/^import\s*\{([^{}]*)\}\s*from\s+'[^']+';\s*$/gm, (all, names) => names
      .split(',').map((n) => n.trim().match(/^([A-Za-z_$][\w$]*)\s+as\s+([A-Za-z_$][\w$]*)$/))
      .filter(Boolean).map(([, from, to]) => `var ${to} = ${from};`).join('\n'))
    // whole import statements, however many lines they span
    .replace(/^import\s[\s\S]*?;\s*$/gm, '')
    // re-exports carry no declaration of their own
    .replace(/^export\s+\*\s+from\s+[^;]*;\s*$/gm, '')
    // A LIST OF NAMES ON ONE LINE, and not a lazy match that crosses them.
    //
    // These two used to read `\{[\s\S]*?\}`, which spans lines: with an
    // `export { A, B };` early in a file and an `export { C } from './x.js';`
    // later, the match started at the first and ran to the second, DELETING
    // every declaration in between. Measured on `core/src/sim.js`: line 51's
    // `export { UNITS, ARMOUR_MASK };` and line 106's `export { TICK_DT } from
    // './tick.js';` swallowed 55 lines, including `export const HALF_X` - and
    // the bundle still carried nine USES of it, so the page threw
    // "HALF_X is not defined" on the first step. The committed bundle predated
    // that re-export, which is the only reason anybody had a working one.
    .replace(/^export\s*\{[^{}]*\}\s*from\s+[^;]*;\s*$/gm, '')
    .replace(/^export\s*\{[^{}]*\}\s*;\s*$/gm, '')
    // and declarations simply lose the keyword
    .replace(/^export\s+(const|function|class|let|var)\s/gm, '$1 ');
  out += '\n// ---- ' + relative(SRC, file) + '\n' + body;
}
// WHAT THE BROWSER BUNDLE OFFERS, AND WHAT IT DELIBERATELY DOES NOT.
//
// `setGround`, `setSolids` and `setHeat` were on this list. All three were
// host doors into the simulated world, and letters 36, 39 and 40 closed them
// in turn: the relief comes from the round's seed, the collision boxes are the
// map's own, and heat is what the core makes of a load that travels in the
// transcript. They still exist in `src/` for the tests that MEASURE what a
// host world was worth - a test is not a page - but a bundle that carried them
// would leave the page able to do what the bridge no longer asks for.
out += '\nreturn { init: init, step: step, hash: hash, runScore: runScore,\n';
out += '         groundAt: groundAt, teleport: teleport,\n';
out += '         restart: restart, frontAt: frontAt, submitLiquidation: submitLiquidation,\n';
out += '         submitLoad: submitLoad, heatOf: heatOf,\n';
out += '         create: create, WORDS: WORDS };\n})();\n';
out += 'if (typeof module !== "undefined") module.exports = BLWP;\n';

mkdirSync(OUT, { recursive: true });
writeFileSync(OUT + 'blwp-core.js', out);

// The package is "type": "module", so Node would read this file as ESM - and
// an ESM file with no export statements has an empty namespace, which is
// exactly the empty object require() was handing back. The browser does not
// care either way; Node needs telling.
writeFileSync(OUT + 'package.json', JSON.stringify({ type: 'commonjs' }, null, 1) + '\n');
console.log('dist/blwp-core.js  ' + (out.length / 1024).toFixed(1) + ' KB  from ' + order.length + ' modules');
